'use strict';
const $=s=>document.querySelector(s), root=$('#root'), modal=$('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v!==''&&v!=null?Number(v).toLocaleString('en-US',{style:'currency',currency:'USD'}):'—';
const when=v=>v?new Date(v).toLocaleString():'—';
const day=v=>v?new Date(v+'T12:00:00').toLocaleDateString():'—';
const today=()=>{let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
let user,csrf='',assets=[],lists={},current=null,tab='Details',page='dashboard',query='',filterStatus='',filterCategory='',sort='description',asc=true,pageNo=1,pageSize=10,selected=new Set();
const statuses=['Available','Checked out','Leased','In repair','Broken','Lost / Missing','Sold','Donated','Disposed'];
const titles={tag:'Asset Tag ID',description:'Description',brand:'Brand',model:'Model',purchase_date:'Purchase Date',cost:'Cost',status:'Status',serial:'Serial No',vendor:'Purchased From',site:'Site',location:'Location',category:'Category',department:'Department',assigned_to:'Assigned To',due_date:'Return Due',warranty_end:'Warranty Ends',notes:'Notes'};
let columns=['tag','description','brand','purchase_date','cost','status'];
const writable=()=>user?.role!=='readonly';
const admin=()=>user?.role==='admin';
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('toast-error',error);el.style.removeProperty('background');el.style.removeProperty('color');el.setAttribute('role',error?'alert':'status');el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',6000)}
async function api(path,options={}){const headers={...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(csrf?{'X-CSRF-Token':csrf}:{}),...options.headers};const r=await fetch('/api'+path,{...options,headers});if(!r.ok){let b=await r.json().catch(()=>({detail:'Request failed.'}));if(r.status===401&&user){user=null;modal.close();login(false);toast('Your session ended. Please sign in again.',true)}throw Error(typeof b.detail==='string'?b.detail:JSON.stringify(b.detail))}return r.status===204?null:r.json()}
function json(method,b){return {method,body:JSON.stringify(b)}}
function panel(title,body,actions=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${actions}</div><div class="panel-body">${body}</div></section>`}
function badge(v){return `<span class="badge ${esc(v.toLowerCase().replace(/[^a-z]+/g,'-').replace(/-$/,''))}">${esc(v)}</span>`}
function button(label,action,cls='',extra=''){return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`}
function nav(label,id,icon){return `<button class="nav-item ${page===id?'active':''}" data-nav="${id}"><span>${icon}</span><span>${label}</span></button>`}
function shell(content,title,subtitle='',actions=''){root.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><strong><b>CMT</b> ASSETS</strong><span>CYBER MATT TECHNOLOGIES</span></div><div class="user"><strong>${esc(user.name)}</strong>${esc({admin:'Administrator',standard:'Standard user',readonly:'Read-only user'}[user.role])}</div><nav>${nav('Dashboard','dashboard','⌂')}<div class="nav-label">Inventory</div>${nav('List of Assets','assets','▤')}${writable()?nav('Add an Asset','add','⊕'):''}${nav('Check Out / In','checkout','⇄')}${nav('Lists','lists','☷')}${nav('Reports','reports','▥')}<div class="nav-label">Account & administration</div>${admin()?nav('Users','users','♙')+nav('Activity Log','history','◷')+nav('Archived Assets','archive','▣')+nav('Backup & Restore','settings','⚙'):''}${nav('My Account','account','♙')}</nav><div class="sidebar-bottom"><small>Local • v1.0.0</small>${button('Sign out','logout','ghost')}</div></aside><main class="main"><div class="page-head"><div><h1>${title}</h1><span class="muted">${subtitle}</span></div><div class="head-actions">${actions}</div></div>${content}<p class="print-only">CMT Asset Manager • Printed ${esc(new Date().toLocaleDateString())}</p></main></div>`}
function field(name,value='',type='text',required=false){let listKey=name==='assigned_to'?'person':name;let dl=lists[listKey];return `<div class="${name==='notes'||name==='description'?'full':''}"><label for="f-${name}">${esc(titles[name]||name)}${required?' <span class="required">*</span>':''}</label>${name==='notes'?`<textarea name="${name}" id="f-${name}">${esc(value)}</textarea>`:name==='status'?`<select id="f-status" name="status">${statuses.map(s=>`<option ${s===value?'selected':''}>${s}</option>`).join('')}</select>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':''} ${dl?'list="dl-'+name+'"':''} ${type==='text'?'maxlength="500"':''}>${dl?`<datalist id="dl-${name}">${dl.map(v=>`<option value="${esc(v.value)}">`).join('')}</datalist>`:''}`}</div>`}
function openModal(title,body,onSubmit,submit='Save'){ $('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-submit').textContent=submit;$('#modal-error').textContent='';$('#modal-form').onsubmit=async e=>{e.preventDefault();$('#modal-submit').disabled=true;try{await onSubmit(Object.fromEntries(new FormData(e.target)));modal.close()}catch(err){$('#modal-error').textContent=err.message}finally{$('#modal-submit').disabled=false}};modal.showModal()}
async function refresh(){[assets,lists]=await Promise.all([api('/assets'),api('/lists')])}
function loadColumns(){try{const v=JSON.parse(localStorage.getItem('cmt-columns-'+user.username));if(Array.isArray(v)&&v.length&&v.every(k=>k in titles))columns=v}catch{}}
async function boot(){try{const state=await api('/state');if(state.setup){login(true);return}try{const m=await api('/me');user=m.user;csrf=m.csrf}catch{login(false);return}loadColumns();await refresh();await navigate('dashboard')}catch(e){root.innerHTML=`<div class="login-page"><div class="login-box"><h1>Unable to start</h1><p class="error">${esc(e.message)}</p><p>Check that the application is running, then refresh this page.</p></div></div>`}}
function login(setup){root.innerHTML=`<div class="login-page"><form class="login-box" id="login-form"><div class="brand"><strong><b>CMT</b> ASSETS</strong><span>CYBER MATT TECHNOLOGIES</span></div><h1>${setup?'Set up your inventory':'Welcome back'}</h1><p class="muted">${setup?'Create your administrator account to get started.':'Sign in to manage your equipment and purchases.'}</p>${setup?'<label for="name">Your name</label><input id="name" name="name" required maxlength="100" autocomplete="name">':''}<label for="username">Username</label><input id="username" name="username" required maxlength="50" autocomplete="username" ${setup?'pattern="[A-Za-z0-9_.\\-]{3,50}"':''}><label for="password">Password${setup?' (at least 12 characters)':''}</label><input id="password" name="password" type="password" ${setup?'minlength="12"':''} maxlength="256" required autocomplete="${setup?'new-password':'current-password'}">${setup?'<label for="confirm">Confirm password</label><input id="confirm" name="confirm" type="password" required autocomplete="new-password">':''}<p id="login-error" class="error" role="alert"></p><button class="primary" type="submit">${setup?'Create administrator':'Sign in'}</button><p class="muted">Stored on this PC • Local access only</p></form></div>`;
// Styling for this static paragraph comes from the shared stylesheet.
$('#login-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));const submit=e.target.querySelector('button');submit.disabled=true;try{if(setup){if(b.password!==b.confirm)throw Error('Passwords do not match.');await api('/setup',json('POST',b))}const r=await api('/login',json('POST',b));user=r.user;csrf=r.csrf;loadColumns();await refresh();await navigate('dashboard')}catch(err){$('#login-error').textContent=err.message;submit.disabled=false}}}
async function navigate(target){page=target;current=null;selected.clear();if(target==='add'){await assetForm();page='assets';renderAssets();return}await refresh();switch(target){case 'dashboard':dashboard();break;case 'assets':case 'checkout':query='';filterStatus=target==='checkout'?'Checked out':'';filterCategory='';pageNo=1;renderAssets();break;case 'lists':renderLists();break;case 'users':await renderUsers();break;case 'history':await renderHistory();break;case 'settings':await renderSettings();break;case 'reports':reports();break;case 'archive':await renderArchive();break;case 'account':account();break}}
function dashboard(){const total=assets.reduce((s,a)=>s+Number(a.cost||0),0);const due=assets.filter(a=>['Checked out','Leased'].includes(a.status)&&a.due_date&&a.due_date<today());const warranty=assets.filter(a=>{let end=new Date(a.warranty_end+'T12:00:00');return a.warranty_end&&end>=new Date(today()+'T00:00:00')&&(end-new Date())/86400000<=30});const cards=[['Total assets',assets.length,'Active inventory records'],['Purchase value',money(total),'Original cost, not current valuation'],['Checked out / leased',assets.filter(a=>['Checked out','Leased'].includes(a.status)).length,'Equipment assigned for use'],['Needs attention',due.length+assets.filter(a=>['Broken','In repair','Lost / Missing'].includes(a.status)).length,'Overdue returns and equipment issues']];const distribution=statuses.map(s=>{let n=assets.filter(a=>a.status===s).length;return n?`<div class="split-row">${badge(s)}<strong>${n}</strong></div>`:''}).join('')||'<p class="muted">Add equipment to see your inventory status.</p>';const attention=[...due.map(a=>[a,'Return overdue: '+day(a.due_date)]),...warranty.map(a=>[a,'Warranty ends: '+day(a.warranty_end)])];shell(`<div class="cards">${cards.map(([l,v,h])=>`<div class="stat"><span class="muted">${l}</span><div class="value">${v}</div><small>${h}</small></div>`).join('')}</div><div class="two-col">${panel('Inventory status',distribution)}${panel('Upcoming & overdue',attention.length?attention.map(([a,n])=>`<div class="split-row"><div><a href="#asset/${a.id}">${esc(a.description)}</a><br><small>${esc(a.tag)}</small></div><small>${esc(n)}</small></div>`).join(''):'<p class="muted">No overdue returns or warranties expiring in the next 30 days.</p>')}</div>${panel('Recently updated',assets.length?simpleAssets([...assets].sort((a,b)=>b.updated.localeCompare(a.updated)).slice(0,5)):'<div class="empty"><strong>Your inventory starts here</strong>Add your first piece of equipment to track its purchase, location, and history.</div>')}`,'Dashboard','Your equipment at a glance',writable()?button('⊕ Add an Asset','add','primary'):'')}
function simpleAssets(rows){return `<div class="table-wrap"><table><thead><tr><th>Asset Tag ID</th><th>Description</th><th>Status</th><th>Cost</th></tr></thead><tbody>${rows.map(a=>`<tr><td class="tag"><a href="#asset/${a.id}">${esc(a.tag)}</a></td><td>${esc(a.description)}</td><td>${badge(a.status)}</td><td>${money(a.cost)}</td></tr>`).join('')}</tbody></table></div>`}
function filtered(){return assets.filter(a=>(!query||Object.values(a).join(' ').toLowerCase().includes(query.toLowerCase()))&&(!filterStatus||a.status===filterStatus)&&(!filterCategory||a.category===filterCategory)).sort((a,b)=>{let v=sort==='cost'?Number(a.cost||0)-Number(b.cost||0):String(a[sort]||'').localeCompare(String(b[sort]||''),undefined,{numeric:true,sensitivity:'base'});return asc?v:-v})}
function renderAssets(){let all=filtered();pageNo=Math.min(pageNo,Math.max(1,Math.ceil(all.length/pageSize)));let start=(pageNo-1)*pageSize,rows=all.slice(start,start+pageSize);shell(`<section class="panel"><div class="panel-head"><h2>⌕ Search Assets</h2><div class="actions"><a href="/api/export.xlsx"><button>Export to Excel</button></a>${button('Setup Columns','columns')}</div></div><div class="toolbar"><input id="search" aria-label="Search assets" placeholder="Search tags, descriptions, serial numbers…" value="${esc(query)}"><select id="filter-status" aria-label="Filter by status"><option value="">All statuses</option>${statuses.map(s=>`<option ${filterStatus===s?'selected':''}>${s}</option>`).join('')}</select><select id="filter-category" aria-label="Filter by category"><option value="">All categories</option>${[...new Set(assets.map(a=>a.category).filter(Boolean))].sort().map(s=>`<option ${filterCategory===s?'selected':''}>${esc(s)}</option>`).join('')}</select></div><div class="toolbar"><select id="page-size" aria-label="Assets per page"><option ${pageSize===10?'selected':''}>10</option><option ${pageSize===25?'selected':''}>25</option><option ${pageSize===50?'selected':''}>50</option></select><span class="muted">assets per page</span>${writable()?button('Change selected status','bulk','','id="bulk-button" '+(!selected.size?'disabled':'')):''}<span class="muted" id="selected-count">${selected.size?selected.size+' selected':''}</span></div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="Select this page" ${rows.length&&rows.every(a=>selected.has(a.id))?'checked':''}></th>${columns.map(k=>`<th><button data-sort="${k}">${titles[k]} ${sort===k?(asc?'▴':'▾'):'↕'}</button></th>`).join('')}<th>Action</th></tr></thead><tbody>${rows.map(a=>`<tr><td><input type="checkbox" data-select="${a.id}" aria-label="Select ${esc(a.tag)}" ${selected.has(a.id)?'checked':''}></td>${columns.map(k=>`<td class="${k==='tag'?'tag':''}">${k==='tag'?`<a href="#asset/${a.id}">${esc(a[k])}</a>`:k==='status'?badge(a[k]):k==='cost'?money(a[k]):k.endsWith('_date')||k==='warranty_end'?day(a[k]):esc(a[k]||'—')}</td>`).join('')}<td><a href="#asset/${a.id}"><button>◉ View</button></a></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="empty"><strong>No assets found</strong>Add an asset or adjust your search filters.</div>':''}<div class="table-footer"><span>Showing ${all.length?start+1:0} to ${Math.min(start+pageSize,all.length)} of ${all.length} records</span><div class="actions">${button('‹ Previous','prev','',pageNo===1?'disabled':'')}<span>${pageNo} / ${Math.max(1,Math.ceil(all.length/pageSize))}</span>${button('Next ›','next','',start+pageSize>=all.length?'disabled':'')}</div></div></section>`,'List of Assets','Track equipment, purchases, and assignments',`${writable()?button('Import CSV','import')+button('⊕ Add an Asset','add','primary'):''}`);$('#search').oninput=e=>{let pos=e.target.selectionStart;query=e.target.value;pageNo=1;renderAssets();$('#search').focus();$('#search').setSelectionRange(pos,pos)};$('#filter-status').onchange=e=>{filterStatus=e.target.value;pageNo=1;renderAssets()};$('#filter-category').onchange=e=>{filterCategory=e.target.value;pageNo=1;renderAssets()};$('#page-size').onchange=e=>{pageSize=+e.target.value;pageNo=1;renderAssets()};$('#select-all').onchange=e=>{rows.forEach(a=>e.target.checked?selected.add(a.id):selected.delete(a.id));renderAssets()}}
async function assetForm(a=null,replicate=false){if(!lists.category)await refresh();let base=a?{...a}:{};if(replicate){base.tag='';base.description=(base.description||'')+' (copy)';base.serial='';base.assigned_to='';base.status='Available';base.due_date=''}const creating=!a||replicate;openModal(creating?'Add an Asset':'Edit Asset',`<div class="grid">${field('description',base.description,'text',true)}${field('tag',base.tag,'text',true)}${field('vendor',base.vendor)}${field('purchase_date',base.purchase_date,'date')}${field('brand',base.brand)}${field('cost',base.cost,'number')}${field('model',base.model)}${field('serial',base.serial)}<div class="section-label">Site, location, category and department</div>${['site','category','location','department'].map(k=>field(k,base[k])).join('')}<div class="section-label">Assignment, warranty and notes</div>${field('status',base.status||'Available')}${field('assigned_to',base.assigned_to)}${field('due_date',base.due_date,'date')}${field('warranty_end',base.warranty_end,'date')}${field('notes',base.notes)}</div><p class="muted">You can enter new list values directly. Add photos and receipts after saving the asset.</p>`,async b=>{let result=await api(creating?'/assets':'/assets/'+a.id,json(creating?'POST':'PUT',{...b,...(!creating?{version:a.version}:{})}));await refresh();await showAsset(result.id);toast(creating?'Asset created.':'Asset updated.')},creating?'Create Asset':'Save Changes')}
function kv(pairs){return `<table class="kv"><tbody>${pairs.map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v}</td></tr>`).join('')}</tbody></table>`}
async function showAsset(id){current=await api('/assets/'+id);page='assets';renderDetail()}
function historyTable(rows){return rows.length?`<div class="table-wrap"><table class="history"><thead><tr><th>When</th><th>User</th><th>Event</th><th>Details</th></tr></thead><tbody>${rows.map(h=>`<tr><td>${esc(when(h.created))}</td><td>${esc(h.actor)}</td><td>${esc(h.event)}</td><td>${historyDetail(h.detail)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No events recorded.</p>'}
function historyDetail(v){try{const b=JSON.parse(v);if(b&&typeof b==='object')return Object.entries(b).map(([k,x])=>`${esc(titles[k]||k)}: ${esc(x.from||'—')} → ${esc(x.to||'—')}`).join('<br>')}catch{}return esc(v)}
function renderDetail(){const a=current,photos=a.attachments.filter(x=>x.kind==='photo'),docs=a.attachments.filter(x=>x.kind!=='photo');let body='';if(tab==='Details'){body=`<h3>Asset Details</h3><div class="grid">${kv([['Serial No',esc(a.serial||'—')],['Purchased From',esc(a.vendor||'—')],['Assigned To',esc(a.assigned_to||'—')]])}${kv([['Created',esc(when(a.created))],['Last Updated',esc(when(a.updated))],['Return Due',esc(day(a.due_date))]])}<div class="full"><h3>Notes</h3><pre>${esc(a.notes||'No notes added.')}</pre></div></div>`}else if(tab==='History'){body=historyTable(a.history)}else if(tab==='Warranty'){body=kv([['Warranty Ends',esc(day(a.warranty_end))],['Status',a.warranty_end?(a.warranty_end<today()?'Expired':'Within warranty period'):'Not recorded']])+`<p class="muted">Attach warranty documents under Docs. Use Edit Asset to update the expiration date.</p>`}else if(tab==='Photos'||tab==='Docs'){let rows=tab==='Photos'?photos:docs;body=`<div class="actions no-print">${writable()?button('Upload '+(tab==='Photos'?'photo':'document'),'upload','success',`data-kind="${tab==='Photos'?'photo':'document'}"`):''}</div><br>${rows.length?(tab==='Photos'?`<div class="gallery">${rows.map(f=>`<div class="photo-card"><a href="/api/attachments/${f.id}" target="_blank" rel="noopener"><img src="/api/attachments/${f.id}/preview" loading="lazy" decoding="async" alt="${esc(f.filename)}"></a><p>${esc(f.filename)}</p>${writable()?button('Remove','remove-file','danger',`data-id="${f.id}"`):''}</div>`).join('')}</div>`:rows.map(f=>`<div class="split-row"><a href="/api/attachments/${f.id}"${/\.pdf$/i.test(f.filename)?' target="_blank" rel="noopener"':''}>${esc(f.filename)}</a><div><small>${(f.size/1024).toFixed(1)} KB</small> ${writable()?button('Remove','remove-file','danger',`data-id="${f.id}"`):''}</div></div>`).join('')):'<div class="empty">No '+tab.toLowerCase()+' attached yet.</div>'}`}const tabs=['Details','Photos','Docs','Warranty','History'];shell(`<section class="panel"><div class="panel-head"><h2>${esc(a.description)}</h2><div class="actions">${button('Print','print')}${writable()?button('✎ Edit Asset','edit')+`<select id="more-actions" aria-label="More asset actions"><option value="">More Actions…</option><option value="status">Change status / Check in or out</option><option value="move">Move / Reassign</option><option value="replicate">Replicate</option>${admin()?'<option value="archive">Archive asset</option>':''}</select>`:''}</div></div><div class="panel-body asset-overview"><div class="asset-photo">${photos.length?`<img src="/api/attachments/${photos[0].id}/preview" decoding="async" fetchpriority="high" alt="${esc(a.description)}">`:'<span>No asset photo</span>'}</div>${kv([['Asset Tag ID',esc(a.tag)],['Purchase Date',esc(day(a.purchase_date))],['Cost',money(a.cost)],['Brand',esc(a.brand||'—')],['Model',esc(a.model||'—')]])}${kv([['Site',esc(a.site||'—')],['Location',esc(a.location||'—')],['Category',esc(a.category||'—')],['Department',esc(a.department||'—')],['Assigned To',esc(a.assigned_to||'—')],['Status',badge(a.status)]])}</div></section><section class="panel"><div class="tabs">${tabs.map(t=>`<button class="${tab===t?'active':''}" data-tab="${t}">${t}</button>`).join('')}</div><div class="panel-body">${body}</div></section>`,'Asset View','Equipment record and lifecycle history',button('‹ Back to List','back'));if($('#more-actions'))$('#more-actions').onchange=async e=>{let action=e.target.value;e.target.value='';try{if(action==='status')statusDialog([a]);if(action==='move')moveDialog();if(action==='replicate')await assetForm(a,true);if(action==='archive'){if(confirm('Archive '+a.tag+'? An administrator can restore it later.')){await api('/assets/'+a.id,json('DELETE',{version:a.version}));await navigate('assets');toast('Asset archived.')}}}catch(err){toast(err.message,true)}}}
function statusDialog(rows){openModal(rows.length===1?'Change Asset Status':`Change Status — ${rows.length} Assets`,`<div class="grid">${field('status',rows.length===1?rows[0].status:'Available')}${field('assigned_to',rows.length===1?rows[0].assigned_to:'')}${field('due_date',rows.length===1?rows[0].due_date:'','date')}</div><br><label><input type="checkbox" id="clear-assignment" name="clear_assignment"> Clear assignee and return date (check in)</label><p class="muted">Assignments are saved for every status, including Available. To check equipment in and remove its assignment, select Available and check the box above. For bulk updates, leave assignee and date blank to keep each existing value.</p>`,async b=>{const clearAssignment=b.clear_assignment==='on';delete b.clear_assignment;if(clearAssignment&&b.status!=='Available')throw Error('Select Available to check equipment in and clear its assignment.');let completed=0;try{for(const a of rows){let values={...a,...b};if(rows.length>1){if(!b.assigned_to)values.assigned_to=a.assigned_to;if(!b.due_date)values.due_date=a.due_date}if(clearAssignment){values.assigned_to='';values.due_date=''}await api('/assets/'+a.id,json('PUT',values));completed++}}catch(err){await refresh();if(current)await showAsset(current.id);else renderAssets();throw Error(`${completed} of ${rows.length} updated. ${err.message}`)}selected.clear();await refresh();if(current)await showAsset(current.id);else renderAssets();toast('Status updated.')})}
function moveDialog(){const a=current;openModal('Move / Reassign',`<div class="grid">${['site','location','department','assigned_to'].map(k=>field(k,a[k])).join('')}</div>`,async b=>{await api('/assets/'+a.id,json('PUT',{...a,...b}));await refresh();await showAsset(a.id);toast('Asset moved.')})}
function uploadDialog(kind){openModal('Upload '+kind,`<label for="attachment">Choose ${kind}</label><input id="attachment" name="attachment" type="file" required ${kind==='photo'?'accept=".png,.jpg,.jpeg,.gif,.webp"':'accept=".png,.jpg,.jpeg,.gif,.webp,.pdf,.txt,.csv,.docx,.xlsx"'}><p class="muted">Maximum 15 MB per file. ${kind==='photo'?'PNG, JPG, GIF, WebP.':'Photos, PDF, TXT, CSV, DOCX, XLSX.'}</p>`,async()=>{let data=new FormData();data.append('file',$('#attachment').files[0]);data.append('kind',kind);await api('/assets/'+current.id+'/attachments',{method:'POST',body:data});await showAsset(current.id);toast('Attachment uploaded.')},'Upload')}
function renderLists(){shell(`<div class="grid">${Object.entries({site:'Sites',location:'Locations',category:'Categories',department:'Departments',person:'People',vendor:'Vendors'}).map(([kind,label])=>panel(label,`<div class="list-items">${(lists[kind]||[]).map(v=>`<span class="list-chip">${esc(v.value)}${admin()?button('×','delete-list','',`data-id="${v.id}" aria-label="Remove ${esc(v.value)} suggestion"`):''}</span>`).join('')||'<span class="muted">No values yet.</span>'}</div>${writable()?button('+ Add '+({site:'site',location:'location',category:'category',department:'department',person:'person',vendor:'vendor'})[kind],'add-list','',`data-kind="${kind}"`):''}`)).join('')}</div>`,'Lists','Manage suggestions used when entering equipment. Removing a suggestion preserves existing asset values.')}
async function renderUsers(){const rows=await api('/users');shell(`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.username)}</td><td>${esc(u.role)}</td><td>${u.active?'Active':'Inactive'}</td><td>${button('Edit','edit-user','',`data-id="${u.id}"`)} ${u.id!==user.id?button('Delete','delete-user','danger',`data-id="${u.id}"`):''}</td></tr>`).join('')}</tbody></table></div></section><p class="muted">Standard users manage inventory. Read-only users view records and export reports. Administrators also manage users, archives, and backups.</p>`,'Users','Manage access to your local inventory',button('+ Add User','add-user','primary'));renderUsers.rows=rows}
function userDialog(u=null){openModal(u?'Edit User — '+u.username:'Add User',`<div class="grid"><div><label for="u-name">Name</label><input id="u-name" name="name" value="${esc(u?.name||'')}" required maxlength="100"></div>${!u?'<div><label for="u-username">Username</label><input id="u-username" name="username" required minlength="3" maxlength="50" autocomplete="off"></div>':''}<div><label for="u-role">Role</label><select id="u-role" name="role">${['admin','standard','readonly'].map(r=>`<option value="${r}" ${(u?.role||'standard')===r?'selected':''}>${{admin:'Administrator',standard:'Standard user',readonly:'Read-only user'}[r]}</option>`).join('')}</select></div><div><label for="u-password">${u?'New password (blank to keep current)':'Password (at least 12 characters)'}</label><input id="u-password" name="password" type="password" minlength="12" maxlength="256" ${u?'':'required'} autocomplete="new-password"></div>${u?`<div><label><input name="active" type="checkbox" ${u.active?'checked':''}> Account active</label></div>`:''}</div><p class="muted">Saving changes signs this user out of all open sessions.</p>`,async b=>{await api(u?'/users/'+u.id:'/users',json(u?'PUT':'POST',{...b,...(u?{active:!!$('#modal-form [name=active]').checked}:{})}));if(u?.id===user.id){user=null;login(false);toast('Account updated. Sign in again.')}else await renderUsers();toast('User saved.')})}
async function renderHistory(){let rows=await api('/history');shell(panel('Recent activity',historyTable(rows)),'Activity Log','Latest 1,000 account and inventory events')}
function reports(){const group=key=>{let map={};assets.forEach(a=>{let k=a[key]||'Unspecified';map[k]??={count:0,cost:0};map[k].count++;map[k].cost+=Number(a.cost||0)});return `<table><thead><tr><th>${titles[key]}</th><th>Assets</th><th>Purchase Value</th></tr></thead><tbody>${Object.entries(map).sort(([a],[b])=>a.localeCompare(b)).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v.count}</td><td>${money(v.cost)}</td></tr>`).join('')}</tbody></table>`};shell(`<div class="notice">Values reflect recorded purchase costs. Blank costs are excluded from value totals. These reports do not calculate depreciation.</div><div class="two-col">${panel('Assets by category',group('category'))}${panel('Assets by site',group('site'))}${panel('Assets by status',group('status'))}${panel('Assets by assignee',group('assigned_to'))}</div>`,'Reports',`${assets.length} active assets • Total purchase value ${money(assets.reduce((s,a)=>s+Number(a.cost||0),0))}`,`<a href="/api/export.xlsx"><button>Export Excel</button></a><a href="/api/export.csv"><button>Export CSV</button></a>${button('Print / Save PDF','print')}`)}
async function renderArchive(){let rows=await api('/archived');shell(panel('Archived inventory',rows.length?`<table><thead><tr><th>Tag</th><th>Description</th><th>Action</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.tag)}</td><td>${esc(a.description)}</td><td>${button('Restore','unarchive','',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table>`:'<p class="muted">No archived assets.</p>'),'Archived Assets','Archived records retain their attachments, unique tags and history.')}
async function renderSettings(){let s=await api('/settings');shell(`${s.pending_restore?'<div class="notice"><strong>A restore is staged.</strong><p>Close CMT Asset Manager, then launch it again. The backup’s accounts and passwords will apply.</p>'+button('Cancel Staged Restore','cancel-restore')+'</div>':''}<div class="two-col">${panel('Back up your inventory','<p>Create a ZIP containing assets, users, history, lists, photos, and documents. Active sessions are excluded.</p><p class="muted">Backups contain business records and password hashes. Store them somewhere protected, ideally on another drive.</p><a href="/api/backup"><button class="primary">Download Full Backup</button></a>')}${panel('Restore a backup','<p>Choose a CMT backup and confirm your administrator password. It will be applied the next time the application starts.</p><p class="muted">A safety copy of the previous database and attachments is kept automatically. Restore replaces the whole inventory.</p>'+button('Choose Backup to Restore','restore','danger'))}</div>${panel('Application details',kv([['Version',esc(s.version)],['Access','This PC only (127.0.0.1)'],['Idle timeout',s.idle_minutes+' minutes'],['Data folder',esc(s.data_directory)]]))}`,'Backup & Restore','Protect your inventory and recover it when needed.')}
function restoreDialog(){openModal('Stage Backup Restore','<div class="notice">This replaces all inventory and user accounts after you restart. Make a current backup first. Sign in afterward using an account from the restored backup.</div><label for="backup-file">CMT backup ZIP (up to 200 MB)</label><input id="backup-file" type="file" accept=".zip" required><br><br><label for="restore-password">Your administrator password</label><input id="restore-password" type="password" required autocomplete="current-password">',async()=>{let data=new FormData();data.append('file',$('#backup-file').files[0]);data.append('password',$('#restore-password').value);await api('/restore',{method:'POST',body:data});await renderSettings();toast('Restore staged. Restart the application to apply it.')},'Validate & Stage Restore')}
function account(){shell(panel('Your account',kv([['Name',esc(user.name)],['Username',esc(user.username)],['Role',esc(user.role)]])+`<br>${button('Change Password','password','primary')}<p class="muted">Changing your password signs out your existing sessions.</p>`),'My Account','Your sign-in and profile')}
function importDialog(){openModal('Import Assets from CSV',`<p><a href="/api/import-template.csv">Download the CSV template</a>, then fill in your equipment. Required columns: <strong>tag</strong> and <strong>description</strong>.</p><p class="muted">Dates use YYYY-MM-DD. Costs use numbers such as 278.99. Tags must be unique. Import adds new assets; it does not overwrite existing ones. All rows must pass validation before anything is imported.</p><label for="csv-file">UTF-8 CSV file (up to 5 MB)</label><input id="csv-file" type="file" accept=".csv" required>`,async()=>{let data=new FormData();data.append('file',$('#csv-file').files[0]);let r=await api('/import',{method:'POST',body:data});await refresh();renderAssets();toast(r.count+' assets imported.')},'Import Assets')}
function columnsDialog(){openModal('Setup Columns',`<div class="columns">${Object.entries(titles).filter(([k])=>k!=='notes').map(([k,v])=>`<label><input type="checkbox" name="col-${k}" ${columns.includes(k)?'checked':''}> ${v}</label>`).join('')}</div>`,async()=>{let values=[...$('#modal-body').querySelectorAll('input:checked')].map(x=>x.name.slice(4));if(!values.length)throw Error('Select at least one column.');columns=values;localStorage.setItem('cmt-columns-'+user.username,JSON.stringify(columns));renderAssets()})}
document.addEventListener('click',async e=>{const close=e.target.closest('[data-close]');if(close){modal.close();return}let link=e.target.closest('a[href^="#asset/"]');if(link){e.preventDefault();try{tab='Details';await showAsset(+link.hash.split('/')[1])}catch(err){toast(err.message,true)}return}const n=e.target.closest('[data-nav]');if(n){try{await navigate(n.dataset.nav)}catch(err){toast(err.message,true)}return}const t=e.target.closest('[data-tab]');if(t){tab=t.dataset.tab;renderDetail();return}const s=e.target.closest('[data-sort]');if(s){if(sort===s.dataset.sort)asc=!asc;else{sort=s.dataset.sort;asc=true}renderAssets();return}const b=e.target.closest('[data-action]');if(!b)return;try{switch(b.dataset.action){case 'logout':await api('/logout',{method:'POST'});user=null;csrf='';login(false);break;case 'add':await assetForm();break;case 'edit':await assetForm(current);break;case 'back':current=null;renderAssets();break;case 'columns':columnsDialog();break;case 'prev':pageNo--;renderAssets();break;case 'next':pageNo++;renderAssets();break;case 'bulk':statusDialog(assets.filter(a=>selected.has(a.id)));break;case 'import':importDialog();break;case 'print':window.print();break;case 'upload':uploadDialog(b.dataset.kind);break;case 'remove-file':if(confirm('Remove this attachment?')){await api('/attachments/'+b.dataset.id,{method:'DELETE'});await showAsset(current.id);toast('Attachment removed.')}break;case 'add-list':openModal('Add List Value','<label for="list-value">Value</label><input id="list-value" name="value" required maxlength="500">',async data=>{await api('/lists',json('POST',{...data,kind:b.dataset.kind}));await refresh();renderLists()});break;case 'delete-list':if(confirm('Remove this suggestion? Existing assets keep their recorded value.')){await api('/lists/'+b.dataset.id,{method:'DELETE'});await refresh();renderLists()}break;case 'add-user':userDialog();break;case 'edit-user':userDialog(renderUsers.rows.find(u=>u.id===+b.dataset.id));break;case 'unarchive':await api('/assets/'+b.dataset.id+'/restore',{method:'POST'});await refresh();await renderArchive();toast('Asset restored.');break;case 'restore':restoreDialog();break;case 'cancel-restore':await api('/restore',{method:'DELETE'});await renderSettings();break;case 'password':openModal('Change Password','<label for="current-password">Current password</label><input id="current-password" name="current" type="password" required autocomplete="current-password"><br><br><label for="new-password">New password (at least 12 characters)</label><input id="new-password" name="password" type="password" required minlength="12" maxlength="256" autocomplete="new-password"><br><br><label for="confirm-password">Confirm new password</label><input id="confirm-password" name="confirm" type="password" required autocomplete="new-password">',async data=>{if(data.password!==data.confirm)throw Error('Passwords do not match.');await api('/password',json('POST',data));user=null;csrf='';login(false);toast('Password changed. Sign in again.')});break}}catch(err){toast(err.message,true)}});
document.addEventListener('change',e=>{let el=e.target.closest('[data-select]');if(el){el.checked?selected.add(+el.dataset.select):selected.delete(+el.dataset.select);$('#selected-count').textContent=selected.size?selected.size+' selected':'';if($('#bulk-button'))$('#bulk-button').disabled=!selected.size}});

// Workspace redesign. Inventory operations above use the same validated API.
const glyphs={boxes:'M4 7h6v6H4z M14 7h6v6h-6z M9 16h6v5H9z M7 3v4 M17 3v4 M12 13v3',home:'M3 11l9-8 9 8 M5 10v11h14V10 M9 21v-7h6v7',monitor:'M3 4h18v13H3z M8 21h8 M12 17v4',history:'M3 5v5h5 M4 9a8 8 0 1 1 0 7 M12 7v5l3 2',chart:'M4 3v17h17 M8 16v-4 M13 16V8 M18 16V5',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',palette:'M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 1-4 2 2 0 0 1 1-4h3a3 3 0 0 0 3-3 9 9 0 0 0-9-7 M7 8h.01 M11 6h.01 M16 8h.01 M6 13h.01',plus:'M12 5v14 M5 12h14',search:'M20 20l-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8 M8 17h6',photo:'M3 4h18v16H3z M3 16l5-5 5 6 3-3 5 5 M15 8h.01',edit:'M4 16L16 4l4 4L8 20H4z M13 7l4 4',arrow:'M5 12h14 M14 7l5 5-5 5',user:'M4 21v-3a8 8 0 0 1 16 0v3 M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8',backup:'M4 6c0-4 16-4 16 0s-16 4-16 0 M4 6v12c0 4 16 4 16 0V6 M4 12c0 4 16 4 16 0',tag:'M3 3h8l10 10-8 8L3 11z M7 7h.01',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',moon:'M20 15A9 9 0 0 1 9 4 9 9 0 1 0 20 15',close:'M5 5l14 14 M19 5L5 19',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',logout:'M10 4H4v16h6 M9 12h12 M16 7l5 5-5 5',pin:'M12 22s8-8 8-14a8 8 0 0 0-16 0c0 6 8 14 8 14 M12 5a3 3 0 1 0 0 6 3 3 0 0 0 0-6'};
function brandIcon(){return `<svg class="icon brand-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="4" width="18" height="5" rx="1.3"/><path d="M5 9v10.5A1.5 1.5 0 0 0 6.5 21h11a1.5 1.5 0 0 0 1.5-1.5V9"/><path d="m8.5 14.5 2.3 2.3 4.7-4.6"/></svg>`}
function ico(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${glyphs[name]||glyphs.monitor}"/></svg>`}
let appearance={mode:'system',accent:'#007f78'},preferencesFor=null,equipmentView='browse';
function applyAppearance(value){document.documentElement.dataset.mode=value.mode;document.documentElement.style.setProperty('--accent-color',value.accent);const rgb=value.accent.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);const l=.2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2];document.documentElement.style.setProperty('--accent-ink',l>.179?'#000000':'#ffffff')}
const refreshData=refresh;
refresh=async function(){await refreshData();if(preferencesFor!==user.username){appearance=await api('/preferences');preferencesFor=user.username;applyAppearance(appearance);globalThis.CmtAppearanceCache?.write(appearance)}};
const originalLogin=login;
login=function(setup){preferencesFor=null;originalLogin(setup);const brand=$('.login-box .brand');if(brand)brand.innerHTML=`<div class="wordmark">${brandIcon()}<div><strong>CMT Asset Manager</strong><span>Your equipment. Your workspace.</span></div></div>`};
function appearanceDialog(){const original={...appearance};let saved=false;openModal('Appearance',`<p class="muted">Choose how your workspace looks. These preferences are saved to your account.</p><div class="appearance-options"><fieldset><legend>Display mode</legend><div class="mode-buttons">${[['light','Light','sun'],['dark','Dark','moon'],['system','System','monitor']].map(([m,t,i])=>`<button type="button" data-mode="${m}" aria-pressed="${appearance.mode===m}">${ico(i)}${t}</button>`).join('')}</div></fieldset><fieldset><legend>Accent color</legend><div class="swatches">${[['#007f78','Teal'],['#245eea','Blue'],['#7953d6','Violet'],['#bd4566','Rose'],['#b65f1a','Copper'],['#447649','Forest'],['#243b64','Navy'],['#0284c7','Sky blue'],['#0891b2','Cyan'],['#6ee7b7','Mint'],['#059669','Emerald'],['#f59e0b','Amber'],['#ea580c','Orange'],['#be123c','Crimson'],['#c026d3','Magenta'],['#64748b','Slate']].map(([c,n])=>`<button type="button" class="swatch" data-accent="${c}" aria-label="${n}" aria-pressed="${appearance.accent===c}"><span class="swatch-dot swatch-${n.toLowerCase().replace(/ /g,'-')}"></span>${n}</button>`).join('')}</div></fieldset><label for="custom-accent">Custom accent color</label><div class="custom-accent"><input type="color" id="custom-accent" value="${appearance.accent}"><code id="accent-value">${appearance.accent.toUpperCase()}</code></div><p class="muted">Button text adapts for contrast. System mode follows your Windows or browser appearance.</p></div>`,async()=>{appearance=await api('/preferences',json('PUT',appearance));saved=true;applyAppearance(appearance);globalThis.CmtAppearanceCache?.write(appearance);toast('Appearance saved to your account.')},'Save Appearance');const update=()=>{applyAppearance(appearance);$('#custom-accent').value=appearance.accent;$('#accent-value').textContent=appearance.accent.toUpperCase();modal.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===appearance.mode)));modal.querySelectorAll('[data-accent]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.accent===appearance.accent)))};$('#modal-body').onclick=e=>{const b=e.target.closest('[data-mode],[data-accent]');if(!b)return;if(b.dataset.mode)appearance.mode=b.dataset.mode;if(b.dataset.accent)appearance.accent=b.dataset.accent;update()};$('#custom-accent').oninput=e=>{appearance.accent=e.target.value;update()};modal.addEventListener('close',()=>{if(!saved){appearance=original;applyAppearance(appearance)}$('#modal-body').onclick=null},{once:true})}
function topNav(label,target,icon,active){return `<button data-nav="${target}" class="top-nav-item ${active?'active':''}">${ico(icon)}${label}</button>`}
shell=function(content,title,subtitle='',actions=''){const workspace=['workspace','users','lists','settings','archive','account'].includes(page);root.innerHTML=`<div class="app-shell"><header class="app-header"><div class="wordmark">${brandIcon()}<div><strong>CMT Asset Manager</strong><span>Your equipment. Your workspace.</span></div></div><div class="header-tools">${button(ico('palette')+'Appearance','appearance')}<span class="profile-name">${esc(user.name)}</span>${button(ico('logout')+'Sign out','logout','ghost')}</div></header><nav class="top-nav" aria-label="Main navigation">${topNav('Overview','dashboard','home',page==='dashboard')}${topNav('Equipment','assets','monitor',['assets','checkout'].includes(page))}${admin()?topNav('Activity','history','history',page==='history'):''}${topNav('Reports','reports','chart',page==='reports')}${topNav('Workspace','workspace','settings',workspace)}</nav><div class="workspace-bar"><span>LOCAL WORKSPACE <span class="version">Version 1.1.2</span></span><span>${ico('backup')}Stored on this PC</span></div><main class="main"><div class="page-head"><div><h1>${esc(title==='Dashboard'?'Workspace overview':title==='List of Assets'?'Equipment':title)}</h1><span class="muted">${esc(subtitle)}</span></div><div class="head-actions">${actions}</div></div>${workspace&&page!=='workspace'?`<div class="workspace-subnav">${button('‹ Workspace settings','workspace')}${button('My account','account')}${admin()?button('People & access','users')+button('Backup & recovery','settings')+button('Archived equipment','archive'):''}${button('Locations & categories','lists')}</div>`:''}${content}<p class="print-only">CMT Asset Manager • Printed ${esc(new Date().toLocaleDateString())}</p></main></div>`};
const navigateOriginal=navigate;
navigate=async function(target){preferencesFor=preferencesFor===user.username?preferencesFor:null;if(target==='workspace'){page='workspace';current=null;await refresh();workspacePage();return}await navigateOriginal(target)};
function workspacePage(){const items=[['Appearance','Choose light, dark, system and your own accent color.','appearance','palette'],['My account','Change your password and view your account.','account','user'],['Locations & categories','Manage sites, locations, categories, people and vendors.','lists','pin'],...(admin()?[['People & access','Add users, manage permissions and deactivate accounts.','users','user'],['Backup & recovery','Download a complete backup or restore your inventory.','settings','backup'],['Archived equipment','Restore equipment without losing its history.','archive','boxes']]:[])];shell(`<div class="settings-grid">${items.map(([t,d,a,i])=>`<section class="setting-tile">${ico(i)}<h2>${t}</h2><p class="muted">${d}</p>${button('Open '+ico('arrow'),a)}</section>`).join('')}</div>`,'Workspace settings','People, organization and preferences in one place.')}
const tableAssets=renderAssets;
function viewButtons(){return `<div class="view-toggle">${button(ico('grid')+'Browse','browse-view',equipmentView==='browse'?'active':'')}${button(ico('list')+'Table','table-view',equipmentView==='table'?'active':'')}</div>`}
function browseList(){const all=filtered();let start=(pageNo-1)*pageSize;pageNo=Math.max(1,Math.min(pageNo,Math.ceil(all.length/pageSize)||1));start=(pageNo-1)*pageSize;return `<aside class="equipment-browser" aria-label="Equipment browser"><div class="browser-search">${ico('search')}<input id="browser-search" placeholder="Find equipment…" aria-label="Search equipment" value="${esc(query)}"></div><div class="browser-filters"><select id="browser-status" aria-label="Filter status"><option value="">All statuses</option>${statuses.map(s=>`<option ${filterStatus===s?'selected':''}>${esc(s)}</option>`).join('')}</select><select id="browser-category" aria-label="Filter category"><option value="">All categories</option>${[...new Set(assets.map(a=>a.category).filter(Boolean))].sort().map(c=>`<option ${filterCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select><select id="browser-sort" aria-label="Sort equipment">${[['description','Name'],['tag','Asset tag'],['cost','Purchase cost'],['purchase_date','Purchase date']].map(([v,t])=>`<option value="${v}" ${sort===v?'selected':''}>${t}</option>`).join('')}</select>${button(asc?'↑ Ascending':'↓ Descending','browse-sort')}</div><div class="browser-records">${all.slice(start,start+pageSize).map(a=>`<div class="browser-record ${current?.id===a.id?'selected':''}">${writable()?`<input type="checkbox" data-select="${a.id}" aria-label="Select ${esc(a.tag)}" ${selected.has(a.id)?'checked':''}>`:''}<a href="#asset/${a.id}" class="record-link"><span class="record-icon">${ico('monitor')}</span><span class="record-label"><strong>${esc(a.description)}</strong><small>${esc(a.tag)}</small><small>${esc(a.site||'No site')} · ${esc(a.status)}</small></span>${ico('arrow')}</a></div>`).join('')||'<div class="empty">No equipment matches your search.</div>'}</div><div class="browser-pagination"><span class="muted">${all.length} records · page ${pageNo}</span>${button('‹','browse-prev','',pageNo===1?'disabled aria-label="Previous page"':'aria-label="Previous page"')}${button('›','browse-next','',start+pageSize>=all.length?'disabled aria-label="Next page"':'aria-label="Next page"')}</div>${writable()?`<div class="bulk-controls">${button('Change selected status','bulk','','id="bulk-button" '+(!selected.size?'disabled':''))}<span id="selected-count" class="muted">${selected.size?selected.size+' selected':''}</span></div>`:''}</aside>`}
function bindBrowser(){const bind=()=>{const el=$('#browser-search');if(el)el.oninput=e=>{let pos=e.target.selectionStart;query=e.target.value;pageNo=1;renderAssets();$('#browser-search').focus();$('#browser-search').setSelectionRange(pos,pos)}};bind();if($('#browser-status'))$('#browser-status').onchange=e=>{filterStatus=e.target.value;pageNo=1;renderAssets()};if($('#browser-category'))$('#browser-category').onchange=e=>{filterCategory=e.target.value;pageNo=1;renderAssets()};if($('#browser-sort'))$('#browser-sort').onchange=e=>{sort=e.target.value;renderAssets()}}
function detailSection(title,icon,body,actions=''){return `<section class="detail-section"><div class="detail-section-head"><h3>${ico(icon)}${title}</h3><div class="actions">${actions}</div></div>${body}</section>`}
function definition(pairs){return `<dl class="definition-grid">${pairs.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl>`}
function equipmentDetail(){if(!current)return `<section class="equipment-empty">${ico('boxes')}<h2>${assets.length?'Select your equipment':'Your workspace starts here'}</h2><p class="muted">${assets.length?'Choose a record to see its photos, purchase details and history.':'Add equipment or import your existing inventory from a backup.'}</p>${writable()?button(ico('plus')+'Add equipment','add','primary'):''}${admin()?button('Restore existing backup','settings'):''}</section>`;const a=current,photos=a.attachments.filter(f=>f.kind==='photo'),docs=a.attachments.filter(f=>f.kind!=='photo');return `<article class="equipment-detail"><header class="equipment-hero"><div class="equipment-hero-photo">${photos.length?`<a href="/api/attachments/${photos[0].id}" target="_blank" rel="noopener"><img src="/api/attachments/${photos[0].id}/preview" decoding="async" fetchpriority="high" alt="${esc(a.description)}"></a>`:ico('monitor')}</div><div class="equipment-hero-info"><div class="eyebrow">${esc(a.tag)}</div><h2>${esc(a.description)}</h2><p class="muted">${esc([a.brand,a.model].filter(Boolean).join(' · ')||'Equipment record')}</p>${badge(a.status)}</div><div class="actions">${writable()?button(ico('edit')+'Edit','edit'):''}${button('Print','print')}</div></header><div class="detail-content"><div class="asset-summary"><div><small>Purchase price</small><strong>${money(a.cost)}</strong></div><div><small>Home base</small><strong>${esc(a.site||'Not recorded')}</strong></div><div><small>Assigned to</small><strong>${esc(a.assigned_to||'Unassigned')}</strong></div></div>${writable()?`<div class="lifecycle-actions">${button('Check out / in · Status','status-dialog')}${button('Move / Reassign','move-dialog')}${button('Replicate','replicate-record')}${admin()?button('Archive','archive-record','danger'):''}</div>`:''}${detailSection('Equipment identity','tag',definition([['Manufacturer',esc(a.brand||'—')],['Model',esc(a.model||'—')],['Serial number',esc(a.serial||'—')],['Category',esc(a.category||'—')],['Current location',esc(a.location||'—')],['Department',esc(a.department||'—')]]))}${detailSection('Purchase & warranty','file',definition([['Purchase date',esc(day(a.purchase_date))],['Purchased from',esc(a.vendor||'—')],['Warranty ends',esc(day(a.warranty_end))],['Return due',esc(day(a.due_date))]]))}${detailSection('Equipment photos','photo',photos.length?`<div class="gallery">${photos.map(f=>`<div class="photo-card"><a href="/api/attachments/${f.id}" target="_blank" rel="noopener"><img src="/api/attachments/${f.id}/preview" loading="lazy" decoding="async" alt="${esc(f.filename)}"></a><p>${esc(f.filename)}</p>${writable()?button('Remove','remove-file','danger',`data-id="${f.id}"`):''}</div>`).join('')}</div>`:'<p class="muted">Add a main equipment photo and additional views.</p>',writable()?button(ico('plus')+'Upload photo','upload','', 'data-kind="photo"'):'')}${detailSection('Files & receipts','file',docs.length?docs.map(f=>`<div class="attachment-row">${ico('file')}<div><a href="/api/attachments/${f.id}"${/\.pdf$/i.test(f.filename)?' target="_blank" rel="noopener"':''}>${esc(f.filename)}</a><small>${(f.size/1024).toFixed(1)} KB · ${esc(when(f.created))}</small></div>${writable()?button('Remove','remove-file','danger',`data-id="${f.id}"`):''}</div>`).join(''):'<p class="muted">Receipts, manuals and warranty documents live here.</p>',writable()?button(ico('plus')+'Attach document','upload','','data-kind="document"'):'')}${detailSection('Notes','edit',`<pre class="asset-notes">${esc(a.notes||'No notes added.')}</pre>`)}${detailSection('Record activity','history',`<details><summary>View ${a.history.length} recorded events</summary>${historyTable(a.history)}</details><p class="muted record-dates">Created ${esc(when(a.created))} · Updated ${esc(when(a.updated))}</p>`)}</div></article>`}
renderAssets=function(){if(equipmentView==='table'&&!current){tableAssets();$('.head-actions').insertAdjacentHTML('afterbegin',viewButtons());return}shell(`<div class="equipment-workspace">${browseList()}${equipmentDetail()}</div>`,'Equipment','A clear view of everything you own.',`${viewButtons()}<a href="/api/export.xlsx"><button>Export Excel</button></a>${writable()?button('Import CSV','import')+button(ico('plus')+'Add equipment','add','primary'):''}`);bindBrowser()};
renderDetail=function(){renderAssets()};
const originalAccount=account;account=function(){originalAccount();$('.panel-body').insertAdjacentHTML('beforeend',`<hr><h3>Personal appearance</h3><p class="muted">Your display mode and accent color are saved with your account.</p>${button(ico('palette')+'Customize appearance','appearance')}`)};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{switch(b.dataset.action){case 'appearance':appearanceDialog();break;case 'workspace':await navigate('workspace');break;case 'users':case 'settings':case 'lists':case 'account':case 'archive':await navigate(b.dataset.action);break;case 'browse-view':equipmentView='browse';current=null;renderAssets();break;case 'table-view':equipmentView='table';current=null;renderAssets();break;case 'browse-sort':asc=!asc;renderAssets();break;case 'browse-prev':pageNo--;renderAssets();break;case 'browse-next':pageNo++;renderAssets();break;case 'status-dialog':statusDialog([current]);break;case 'move-dialog':moveDialog();break;case 'replicate-record':await assetForm(current,true);break;case 'archive-record':if(confirm('Archive '+current.tag+'? You can restore it from Workspace later.')){await api('/assets/'+current.id,json('DELETE',{version:current.version}));await navigate('assets');toast('Equipment archived.')}break}}catch(err){toast(err.message,true)}});
appearance=globalThis.CmtAppearanceCache?.read()||appearance;
applyAppearance(appearance);

function deleteUserDialog(target){
    openModal('Delete User — '+target.username,
        `<div class="notice"><strong>Permanently delete this login account?</strong><p>Equipment, existing Assigned To values and past activity will be kept. This user will be signed out immediately.</p></div><label for="delete-username">Type ${esc(target.username)} to confirm</label><input id="delete-username" name="username" required autocomplete="off"><p class="muted">To temporarily block access, mark the account inactive instead.</p>`,
        async b=>{await api('/users/'+target.id,json('DELETE',{username:b.username}));await renderUsers();toast('User account deleted. Inventory and history retained.');},'Delete User');
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action="delete-user"]');if(b){const target=renderUsers.rows?.find(u=>u.id===Number(b.dataset.id));if(target)deleteUserDialog(target);else toast('Reload the user list and try again.',true);}});

boot();
